+type cpuController struct {
+	baseController
+	cpus float32
+}
+
+func (c cpuController) apply() error {
+	const (
+		period = 100000
+	)
+	limit := c.cpus * period
+	value := fmt.Sprintf("%f %d", limit, period)
+
+	return errors.WithStack(c.baseController.apply(cpuMax, value))
